package android.graphics; import java.awt.image.BufferedImage; public class Bitmap {public enum Config{ARGB_8888} public static Bitmap createBitmap(int[] pixels,int w,int h,Config c){BufferedImage image=new BufferedImage(w,h,BufferedImage.TYPE_INT_ARGB);image.setRGB(0,0,w,h,pixels,0,w);return new Bitmap(image);} public final BufferedImage pixels;private boolean recycled;public Bitmap(BufferedImage p){pixels=p;}public int getWidth(){return pixels.getWidth();}public int getHeight(){return pixels.getHeight();}public void recycle(){recycled=true;}public boolean isRecycled(){return recycled;}}
